root.addEventListener('input',e=>{if(!active)return;if(e.target.dataset.cnName!==undefined){names[Number(e.target.dataset.cnName)]=e.target.value;return;}if(e.target.id==='cn-answer'){draft=e.target.value;const b=main.querySelector('#cn-lock');if(b)b.disabled=!draft.trim();saveSession();}});
root.addEventListener('change',e=>{if(!active&&!externalHelp)return;if(['tm-language','cn-welcome-language'].includes(e.target.id)){app.language=e.target.value==='es-419'?'es':'en';window.tryMeSettings?.rememberLanguage();render();}if(e.target.id==='cn-region'){country=e.target.value;renderDialog(false);}});
root.addEventListener('click',e=>{if(!active&&!externalHelp)return;clearNotice();let b=e.target.closest('button');if(M?.busy&&!e.target.closest('[data-action="rulesmenu"]'))M.flush();if(b&&b.isConnected===false&&b.dataset.cn)b=main.querySelector('[data-cn="'+b.dataset.cn+'"]');if(!b||b.disabled)return;if(b.dataset.action==='rulesmenu'){openMenu();return;}const a=b.dataset.cn;if(!a)return;app.click();if(M?.intercept(a,b,motionContext(),()=>performAction(a,b)))return;performAction(a,b);
});
function emitMotion(action){if(!active)return;app.click();if(!M?.intercept(action,null,motionContext(),()=>performAction(action,{dataset:{}})))performAction(action,{dataset:{}});}
function performAction(a,b){
 if(a==='resumeSaved'&&awaitingResume){awaitingResume=false;unpause();render();return;}if(a==='endSaved'&&awaitingResume){finish(false);return;}
 if(awaitingResume&&!['help','rules','about','finishask','menuback','closemenu','finishnow','gamesask','confirmgames','games','pauseleave','finishleave'].includes(a))return;
 if(a==='flip'&&phase==='cardback'){phase=flipTarget;render();return;}if(a==='finishSpeaking'){if(pencilPasses>=3)return;pencilPasses++;usSpeaker=conversationReady?1-usSpeaker:speaker;conversationReady=true;render();return;}if(a==='switchSpeaker'){if(pencilPasses>=3)return;pencilPasses++;usSpeaker=1-usSpeaker;render();return;}
 if(a==='games'){exit();return;}if(a==='crave'){exit(true);return;}if(a==='welcome'){try{localStorage.setItem('tryme-connect-welcome','yes');}catch{}view='setup';render();return;}
 if(a==='duration'&&view==='setup'){minutes=Number(b.dataset.value);render();return;}if(a==='start'&&view==='setup'){start();return;}if(a==='again'){awaitingResume=false;clearSession();s=null;view='setup';render();return;}
 if(a==='pauseleave'){pause();saveSession();exit(false,true);return;}if(a==='finishleave'){finish(false);exit();return;}
 if(a==='gamesask'){if(s&&view!=='final')openMenu(a);else exit();return;}if(a==='confirmgames'){exit();return;}
 if(['help','rules','about','finishask'].includes(a)){openMenu(a);return;}if(a==='menuback'){if(externalHelp)closeMenu();else openMenu();return;}if(a==='closemenu'){closeMenu();return;}if(a==='finishnow'){finish(false);return;}
 if(a==='pass'){pass();return;}if(a==='lighter'){s.depthCeiling=2;s.forceLight=true;s.consecutivePass=0;select();return;}
 if(a==='voteready'&&view==='permission-handoff'){view='permission';render();return;}
 if((a==='yes'||a==='no')&&view==='permission'){votes.push(a==='yes');if(permissionTurn===0){permissionTurn=1;view='permission-handoff';}else{s.permissions[permissionKind]=votes.every(Boolean);votes=[];view='permission-result';}render();return;}
 if(a==='permissioncontinue'&&view==='permission-result'){const c=pendingCard;pendingCard=null;if(s.permissions[permissionKind]&&ratio()<.85)showCard(c);else select();return;}
 if(a==='ready'&&view==='handoff'){view='card';phase='answer';draft='';pickOther=false;render();return;}
 if(a==='option'&&phase==='answer'){const options=current.options?.[language()]||[];answers[answerTurn]=options[Number(b.dataset.option)]||'';draft='';pickOther=false;render();return;}
 if(a==='other'&&phase==='answer'){answers[answerTurn]='';draft='';pickOther=true;render();main.querySelector('#cn-answer')?.focus();return;}
 if(a==='otherback'&&phase==='answer'){pickOther=false;draft='';render();return;}
 if(a==='lock'&&phase==='answer'){const answer=String(main.querySelector('#cn-answer')?.value||answers[answerTurn]||'').trim();if(!answer)return;answers[answerTurn]=answer;draft='';pickOther=false;if(answerTurn===speaker){answerTurn=1-speaker;view='handoff';}else{view='card';phase='readyreveal';}render();return;}
 if(a==='reveal'&&phase==='readyreveal'){phase='reveal';render();return;}if(a.startsWith('rate')&&phase==='reveal'&&E.family(current)==='GUESS'){score=Number(a.slice(-1));phase='after';render();return;}
 if(a==='spokenNext'&&phase==='spoken'){spokenTurn=1;pencilPasses=1;conversationReady=false;render();return;}if(a==='reflect'&&phase==='speak'){phase='reflect';render();return;}if(a==='speakagain'&&phase==='reflect'&&!moreUsed){moreUsed=true;phase='speak';render();return;}
 if(a==='touch'||a==='notouch'){s.noTouch=a==='notouch';phase='do';render();return;}if(a==='doStart'&&phase==='do'&&current.timer_s!=null&&!stepEnd){doFinished=false;stepEnd=Date.now()+current.timer_s*1000;render();return;}
 if(a==='doNext'&&phase==='do'&&doFinished&&doTurn===0&&current.timer_turns===2){doTurn=1;doFinished=false;stepEnd=0;render();return;}
 if(a==='doEarly'&&phase==='do'&&stepEnd&&!doFinished&&Date.now()>=stepEnd-current.timer_s*500){doFinished=true;stepEnd=Date.now();render();return;}
 if(a==='doDone'&&phase==='do'&&(current.timer_s==null||doFinished&&doTurn===(current.timer_turns||1)-1)){next();return;}
 if(a==='roundStart'&&['roundintro','roundready'].includes(phase)){if(phase==='roundintro'){roundIndex=0;roundMarks=[];}phase='round';stepEnd=Date.now()+3000;render();return;}
 if(['matched','nope','inTime','stuck','skip'].includes(a)&&phase==='round'){
  if(['matched','nope'].includes(a)&&Date.now()<stepEnd)return;if(a!=='skip'){total++;if(['matched','inTime'].includes(a))hits++;}roundMarks.push(a==='skip'?'skip':['matched','inTime'].includes(a)?'hit':'miss');roundIndex++;if(roundIndex>=current.items.length){phase='after';stepEnd=0;roundHitsTotal+=hits;roundCountTotal+=total;}else if(M&&E.family(current)==='WHO'){phase='roundready';stepEnd=0;}else stepEnd=Date.now()+3000;render();return;
 }
 if(a==='after'){phase='after';stepEnd=0;render();return;}if(a==='stay'&&current?.second_layer&&ratio()<.85){phase='layer';render();return;}if(a==='next'){next();return;}
}
